#!/bin/bash
# Runs once after the first boot of the installed Proxmox VE ([first-boot] in the answer file).
# The settings block below is generated by build-iso.sh. Log: /var/log/first-boot-custom.log
set -u

LOG=/var/log/first-boot-custom.log
STATUS=/var/lib/first-boot-custom.status
exec >>"$LOG" 2>&1
echo "=== first boot $(date) ==="

#@@SETTINGS@@

FAILED=()
step() {
    local name=$1
    shift
    echo "--- $name"
    if "$@"; then
        echo "ok: $name"
    else
        echo "FAILED: $name"
        FAILED+=("$name")
    fi
}

wait_for_network() {
    # HTTP instead of ping: ICMP is blocked in many networks, apt needs HTTP anyway
    for _ in $(seq 1 36); do
        curl -fsSI --max-time 5 http://deb.debian.org/debian/ >/dev/null 2>&1 && return 0
        sleep 5
    done
    echo "no network after 3 minutes"
    return 1
}

# ---- Storage ----------------------------------------------------------------

storage_vps() {
    # One global storage: the root volume takes the whole disk
    lvextend -l +100%FREE -r /dev/pve/root || return 1
    pvesm remove local-lvm 2>/dev/null || true
    pvesm set local --content iso,vztmpl,backup,snippets,images,rootdir
}

storage_baremetal() {
    # ZFS install: "local" (directory) and "local-zfs" (VM disks) exist already
    pvesm set local --content iso,vztmpl,backup,snippets
}

# ---- Proxmox ----------------------------------------------------------------

cluster_options() {
    pvesh set /cluster/options --keyboard "$KEYBOARD"
}

apt_repos() {
    local f
    for f in /etc/apt/sources.list.d/pve-enterprise.sources /etc/apt/sources.list.d/ceph.sources; do
        if [ -f "$f" ] && ! grep -q '^Enabled: no' "$f"; then
            sed -i '$a Enabled: no' "$f"
        fi
    done
    cat > /etc/apt/sources.list.d/proxmox-no-subscription.sources <<'APT'
Types: deb
URIs: http://download.proxmox.com/debian/pve
Suites: trixie
Components: pve-no-subscription
Signed-By: /usr/share/keyrings/proxmox-archive-keyring.gpg
APT
}

subscription_nag() {
    # Hides the "No valid subscription" pop-up of the web interface. An apt hook repeats the patch
    # after every update of proxmox-widget-toolkit.
    cat > /usr/local/sbin/pve-hide-subscription-nag <<'NAG'
#!/bin/bash
F=/usr/share/javascript/proxmox-widget-toolkit/proxmoxlib.js
[ -f "$F" ] || exit 0
grep -q "void({ //Ext.Msg.show" "$F" && exit 0
sed -Ezi.bak "s/(Ext.Msg.show\(\{\s+title: gettext\('No valid sub)/void\(\{ \/\/\1/g" "$F"
grep -q "void({ //Ext.Msg.show" "$F" && systemctl restart pveproxy.service
exit 0
NAG
    chmod 755 /usr/local/sbin/pve-hide-subscription-nag
    cat > /etc/apt/apt.conf.d/99-pve-hide-subscription-nag <<'HOOK'
DPkg::Post-Invoke { "/usr/local/sbin/pve-hide-subscription-nag || true"; };
HOOK
    /usr/local/sbin/pve-hide-subscription-nag
    grep -q "void({ //Ext.Msg.show" /usr/share/javascript/proxmox-widget-toolkit/proxmoxlib.js
}

dns() {
    # Proxmox and glibc use at most three resolvers, the rest is ignored
    local args=(--search "${FQDN#*.}") i=1 d
    for d in $DNS_SERVERS; do
        if [ "$i" -le 3 ]; then
            args+=("--dns$i" "$d")
        else
            echo "note: resolver $d is not used (limit of three)"
        fi
        i=$((i + 1))
    done
    pvesh set "/nodes/$(hostname -s)/dns" "${args[@]}"
}

host_auto_updates() {
    # Debian security updates only, no automatic reboot. Proxmox packages are updated by hand.
    apt-get update || return 1
    DEBIAN_FRONTEND=noninteractive apt-get install -y unattended-upgrades || return 1
    cat > /etc/apt/apt.conf.d/20auto-upgrades <<'APTC'
APT::Periodic::Update-Package-Lists "1";
APT::Periodic::Unattended-Upgrade "1";
APT::Periodic::AutocleanInterval "7";
APTC
    cat > /etc/apt/apt.conf.d/52host-unattended <<'APTC'
Unattended-Upgrade::Automatic-Reboot "false";
Unattended-Upgrade::Remove-Unused-Kernel-Packages "true";
APTC
}

# ---- Security ---------------------------------------------------------------

ssh_hardening() {
    mkdir -p /etc/ssh/sshd_config.d
    cat > /etc/ssh/sshd_config.d/10-hardening.conf <<'SSHD'
PermitRootLogin prohibit-password
PasswordAuthentication no
KbdInteractiveAuthentication no
MaxAuthTries 3
LoginGraceTime 30
X11Forwarding no
AllowAgentForwarding no
SSHD
    sshd -t && { systemctl reload ssh 2>/dev/null || systemctl reload sshd; }
}

kernel_hardening() {
    cat > /etc/sysctl.d/98-hardening.conf <<'SYSCTL'
net.ipv4.tcp_syncookies = 1
net.ipv4.icmp_echo_ignore_broadcasts = 1
net.ipv4.icmp_ignore_bogus_error_responses = 1
net.ipv4.conf.all.accept_source_route = 0
net.ipv4.conf.default.accept_source_route = 0
net.ipv6.conf.all.accept_source_route = 0
net.ipv4.conf.all.accept_redirects = 0
net.ipv4.conf.default.accept_redirects = 0
net.ipv6.conf.all.accept_redirects = 0
net.ipv4.conf.all.send_redirects = 0
kernel.dmesg_restrict = 1
kernel.kptr_restrict = 2
SYSCTL
    sysctl --system >/dev/null
}

reduce_services() {
    # rpcbind listens on port 111 on all interfaces and is only needed for NFSv3 storage
    systemctl disable --now rpcbind.service rpcbind.socket 2>/dev/null || true
    # Mail stays local
    if command -v postconf >/dev/null; then
        postconf -e 'inet_interfaces = loopback-only'
        systemctl reload postfix 2>/dev/null || true
    fi
    systemctl enable --now chrony 2>/dev/null || true
}

fail2ban_setup() {
    apt-get update || return 1
    DEBIAN_FRONTEND=noninteractive apt-get install -y fail2ban || return 1
    local ignore="127.0.0.1/8 ::1"
    [ -n "$MGMT_ALLOWED" ] && ignore="$ignore $MGMT_ALLOWED"
    cat > /etc/fail2ban/filter.d/proxmox.conf <<'F2B'
[Definition]
failregex = pvedaemon\[.*authentication failure; rhost=<HOST> user=.* msg=.*
ignoreregex =
journalmatch = _SYSTEMD_UNIT=pvedaemon.service
F2B
    cat > /etc/fail2ban/jail.d/proxmox.local <<F2B
[DEFAULT]
ignoreip = $ignore
bantime = 1h
findtime = 10m

[sshd]
enabled = true
backend = systemd
maxretry = 4

[proxmox]
enabled = true
port = https,http,8006
filter = proxmox
backend = systemd
maxretry = 3
F2B
    systemctl enable --now fail2ban
    systemctl restart fail2ban
}

host_firewall() {
    local c
    {
        echo "[OPTIONS]"
        echo "enable: 1"
        echo "policy_in: DROP"
        echo "policy_out: ACCEPT"
        echo
        echo "[IPSET mgmt]"
        for c in $MGMT_ALLOWED; do echo "$c"; done
        echo
        echo "[RULES]"
        echo "IN ACCEPT -source +mgmt -p tcp -dport 22"
        echo "IN ACCEPT -source +mgmt -p tcp -dport 8006"
        echo "IN ACCEPT -p icmp"
        echo "IN ACCEPT -p ipv6-icmp"
        echo "IN ACCEPT -p udp -sport 67 -dport 68"
        if [ "$PRIVATE_NET" = "true" ]; then
            # VMs on the private bridge may use DHCP and DNS of the host
            echo "IN ACCEPT -iface vmbr1 -p udp -dport 67"
            echo "IN ACCEPT -iface vmbr1 -p udp -dport 53"
            echo "IN ACCEPT -iface vmbr1 -p tcp -dport 53"
        fi
    } > /etc/pve/firewall/cluster.fw
    systemctl enable --now pve-firewall
}

# ---- Network ----------------------------------------------------------------

forwarding() {
    cat > /etc/sysctl.d/99-ip-forwarding.conf <<'SYSCTL'
net.ipv4.ip_forward = 1
net.ipv6.conf.all.forwarding = 1
SYSCTL
    sysctl --system >/dev/null
}

ipv6_config() {
    mkdir -p /etc/network/interfaces.d
    {
        echo "iface vmbr0 inet6 static"
        echo "    address $IPV6_CIDR"
        if [ "$IPV6_GATEWAY_ONLINK" = "true" ]; then
            # Gateway outside of the prefix (routed /64)
            echo "    post-up ip -6 route replace default via $IPV6_GATEWAY dev vmbr0 onlink"
            echo "    pre-down ip -6 route del default via $IPV6_GATEWAY dev vmbr0 onlink || true"
        else
            echo "    gateway $IPV6_GATEWAY"
        fi
    } > /etc/network/interfaces.d/10-ipv6.cfg
}

private_net() {
    mkdir -p /etc/network/interfaces.d
    {
        echo "auto vmbr1"
        echo "iface vmbr1 inet static"
        echo "    address $PRIVATE_NET_CIDR"
        echo "    bridge-ports none"
        echo "    bridge-stp off"
        echo "    bridge-fd 0"
        if [ "$PRIVATE_NET_NAT" = "true" ]; then
            echo "    post-up /usr/local/sbin/vmbr1-nat up"
            echo "    post-down /usr/local/sbin/vmbr1-nat down"
        fi
    } > /etc/network/interfaces.d/20-vmbr1.cfg

    if [ "$PRIVATE_NET_NAT" = "true" ]; then
        cat > /usr/local/sbin/vmbr1-nat <<NAT
#!/bin/bash
# Source NAT for the private network (VMs on vmbr1 reach the internet through vmbr0)
RULE="POSTROUTING -s $PRIVATE_NET_NETWORK -o vmbr0 -j MASQUERADE"
case "\$1" in
    up)   iptables -t nat -C \$RULE 2>/dev/null || iptables -t nat -A \$RULE ;;
    down) iptables -t nat -D \$RULE 2>/dev/null || true ;;
esac
NAT
        chmod 755 /usr/local/sbin/vmbr1-nat
    fi
}

private_dhcp() {
    # dnsmasq answers DHCP and DNS on vmbr1 only. The config is written before the package is installed,
    # so it never listens on the public interface.
    mkdir -p /etc/dnsmasq.d /etc/systemd/system/dnsmasq.service.d
    cat > /etc/dnsmasq.d/vmbr1.conf <<DNSMASQ
interface=vmbr1
bind-dynamic
dhcp-range=$PRIVATE_NET_DHCP_START,$PRIVATE_NET_DHCP_END,$PRIVATE_NET_MASK,12h
dhcp-option=option:router,$PRIVATE_NET_ADDRESS
dhcp-option=option:dns-server,$PRIVATE_NET_ADDRESS
no-resolv
server=1.1.1.1
server=8.8.8.8
DNSMASQ
    cat > /etc/systemd/system/dnsmasq.service.d/override.conf <<'UNIT'
[Unit]
After=network-online.target
Wants=network-online.target
UNIT
    systemctl daemon-reload
    apt-get update || return 1
    DEBIAN_FRONTEND=noninteractive apt-get install -y dnsmasq || return 1
    systemctl enable dnsmasq
    systemctl restart dnsmasq
}

interface_snippets() {
    mkdir -p /etc/network/interfaces.d
    echo "$SNIPPETS_B64" | base64 -d | tar -xzf - -C /etc/network/interfaces.d
}

network_reload() {
    grep -q '^source /etc/network/interfaces.d/' /etc/network/interfaces \
        || echo 'source /etc/network/interfaces.d/*' >> /etc/network/interfaces
    ifreload -a
}

static_routes() {
    echo "$ROUTES_B64" | base64 -d > /etc/proxmox-static-routes.conf
    cat > /usr/local/sbin/apply-static-routes <<'APPLY'
#!/bin/bash
# Applies /etc/proxmox-static-routes.conf (syntax of "ip route", prefix "-6 " for IPv6)
rc=0
while IFS= read -r line; do
    [[ "$line" =~ ^[[:space:]]*(#|$) ]] && continue
    if [[ "$line" == -6\ * ]]; then
        # shellcheck disable=SC2086
        ip -6 route replace ${line#-6 } || rc=1
    else
        # shellcheck disable=SC2086
        ip route replace $line || rc=1
    fi
done < /etc/proxmox-static-routes.conf
exit $rc
APPLY
    chmod 755 /usr/local/sbin/apply-static-routes
    cat > /etc/systemd/system/static-routes.service <<'UNIT'
[Unit]
Description=Apply static routes
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/usr/local/sbin/apply-static-routes

[Install]
WantedBy=multi-user.target
UNIT
    systemctl daemon-reload
    systemctl enable --now static-routes.service
}

# ---- VM templates -----------------------------------------------------------

vm_templates() {
    local storage=local
    [ "$TARGET" = "baremetal" ] && storage=local-zfs
    apt-get update || return 1
    DEBIAN_FRONTEND=noninteractive apt-get install -y libguestfs-tools wget || return 1
    rm -rf /opt/template-generator
    mkdir -p /opt/template-generator
    echo "$TEMPLATES_B64" | base64 -d | tar -xzf - -C /opt/template-generator || return 1
    cd /opt/template-generator || return 1
    local t rc=0
    for t in $TEMPLATES; do
        echo "--- template $t"
        DEFAULT_STORAGE=$storage DEFAULT_BRIDGE=vmbr0 TEMPLATE_IPCONFIG=ip=dhcp \
            BRAND_DOCS_URL="$BRAND_DOCS_URL" BRAND_SUPPORT_URL="$BRAND_SUPPORT_URL" \
            bash generate-template.sh "$t" </dev/null || { echo "template $t failed"; rc=1; }
    done
    return $rc
}

template_refresh() {
    local storage=local
    [ "$TARGET" = "baremetal" ] && storage=local-zfs
    cat > /etc/default/template-refresh <<ENVF
DEFAULT_STORAGE="$storage"
DEFAULT_BRIDGE="vmbr0"
TEMPLATE_IPCONFIG="ip=dhcp"
BRAND_DOCS_URL="$BRAND_DOCS_URL"
BRAND_SUPPORT_URL="$BRAND_SUPPORT_URL"
TEMPLATES="$TEMPLATES"
ENVF
    cat > /usr/local/sbin/refresh-templates <<'REFRESH'
#!/bin/bash
# Rebuilds the VM templates from the current cloud images (monthly, by template-refresh.timer).
# Templates that still have linked clones are kept: Proxmox refuses to destroy them.
set -u
. /etc/default/template-refresh
export DEFAULT_STORAGE DEFAULT_BRIDGE TEMPLATE_IPCONFIG BRAND_DOCS_URL BRAND_SUPPORT_URL ASSUME_YES=1 REFRESH_IMAGE=1
cd /opt/template-generator || exit 1
rc=0
for t in $TEMPLATES; do
    echo "--- $(date) refreshing $t"
    bash generate-template.sh "$t" </dev/null || { echo "failed: $t"; rc=1; }
done
exit $rc
REFRESH
    chmod 755 /usr/local/sbin/refresh-templates
    cat > /etc/systemd/system/template-refresh.service <<'UNIT'
[Unit]
Description=Rebuild VM templates from current cloud images
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
TimeoutStartSec=2h
ExecStart=/usr/local/sbin/refresh-templates
UNIT
    cat > /etc/systemd/system/template-refresh.timer <<'UNIT'
[Unit]
Description=Monthly VM template refresh

[Timer]
OnCalendar=monthly
RandomizedDelaySec=6h
Persistent=true

[Install]
WantedBy=timers.target
UNIT
    systemctl daemon-reload
    systemctl enable --now template-refresh.timer
}

# ---- Run --------------------------------------------------------------------

if [ "$TARGET" = "vps" ]; then
    step "storage (one global storage)" storage_vps
else
    step "storage (zfs)" storage_baremetal
fi
step "cluster options" cluster_options
step "apt repositories" apt_repos
[ "$SUBSCRIPTION_NAG" = "hide" ] && step "hide subscription pop-up" subscription_nag
step "dns" dns
step "network" wait_for_network
[ "$HOST_AUTO_UPDATE" = "security" ] && step "automatic security updates" host_auto_updates

if [ "$HARDENING" = "true" ]; then
    step "ssh hardening" ssh_hardening
    step "kernel hardening" kernel_hardening
    step "reduce services" reduce_services
    step "fail2ban" fail2ban_setup
fi

[ "$IP_FORWARDING" = "true" ] && step "ip forwarding" forwarding
[ -n "$IPV6_CIDR" ] && [ -n "$IP_CIDR" ] && step "ipv6" ipv6_config
[ "$PRIVATE_NET" = "true" ] && step "private network vmbr1" private_net
[ "$PRIVATE_NET" = "true" ] && [ "$PRIVATE_NET_DHCP" = "true" ] && step "dhcp on vmbr1" private_dhcp
[ -n "$SNIPPETS_B64" ] && step "interface snippets" interface_snippets
step "network reload" network_reload
[ -n "$ROUTES_B64" ] && step "static routes" static_routes
[ -n "$MGMT_ALLOWED" ] && step "host firewall" host_firewall

if [ -n "$TEMPLATES" ]; then
    step "vm templates" vm_templates
    [ "$TEMPLATE_AUTO_REFRESH" = "true" ] && step "monthly template refresh" template_refresh
fi

if [ "${#FAILED[@]}" -eq 0 ]; then
    echo "OK $(date)" > "$STATUS"
    echo "=== first boot finished without errors ==="
else
    echo "FAILED: ${FAILED[*]}" > "$STATUS"
    echo "=== first boot finished with errors: ${FAILED[*]} ==="
fi
